#!/usr/bin/env python3
"""
Export AI Coding sessions from staging into the demo repo's logs/ directory.

Staging path:  ~/.claude/contest-collector-staging/<github_login>/<date>/<tool>__<sid>.jsonl
Target path:   <repo_root>/logs/<github_login>/<date>/<tool>__<sid>.jsonl

Normally sessions auto-export into the demo repo's logs/ at session end
(see the adapters). This script is the manual path: list, re-export, or
selectively export staged sessions.

Usage:
  python3 tools/export-session.py --latest
  python3 tools/export-session.py --session <session-id>
  python3 tools/export-session.py --since <date>
  python3 tools/export-session.py --all
  python3 tools/export-session.py --list
"""
from __future__ import annotations

import argparse
import json
import shutil
import subprocess
import sys
from datetime import datetime, timedelta, timezone
from pathlib import Path


def staging_root() -> Path:
    return Path.home() / ".claude" / "contest-collector-staging"


def _load_env_github_login() -> str | None:
    env_file = Path.home() / ".claude" / "contest-collector.env"
    if not env_file.is_file():
        return None
    try:
        for line in env_file.read_text(encoding="utf-8").splitlines():
            if line.startswith("GITHUB_LOGIN="):
                val = line.split("=", 1)[1].strip().strip('"').strip("'")
                return val or None
    except Exception:
        return None
    return None


def repo_root() -> Path | None:
    try:
        out = subprocess.check_output(
            ["git", "rev-parse", "--show-toplevel"],
            stderr=subprocess.PIPE, text=True,
        )
        return Path(out.strip())
    except Exception:
        return None


def list_sessions(github_login: str | None) -> list[dict]:
    root = staging_root()
    if not root.exists():
        return []
    if github_login is None:
        env_login = _load_env_github_login()
        if env_login:
            github_login = env_login
    sessions = []
    for member_dir in sorted(root.iterdir()):
        if not member_dir.is_dir() or member_dir.name == "errors":
            continue
        if github_login and member_dir.name != github_login:
            continue
        manifest_path = member_dir / "manifest.json"
        if not manifest_path.exists():
            continue
        try:
            manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
        except Exception:
            continue
        for s in manifest.get("sessions", []):
            sessions.append({
                "github_login": member_dir.name,
                "session_id": s.get("session_id"),
                "tool": s.get("tool"),
                "started_at": s.get("started_at", ""),
                "last_event_at": s.get("last_event_at", ""),
                "event_count": s.get("event_count", 0),
                "file_path": s.get("file_path", ""),
                "model": s.get("model", ""),
            })
    return sessions


def filter_sessions(sessions: list[dict], args) -> list[dict]:
    if args.session:
        return [s for s in sessions if s["session_id"] == args.session]
    if args.latest:
        if not sessions:
            return []
        return [max(sessions, key=lambda s: s.get("last_event_at") or "")]
    if args.since:
        try:
            cutoff = datetime.fromisoformat(args.since.replace("Z", "+00:00"))
        except ValueError:
            cutoff = datetime.combine(
                datetime.strptime(args.since, "%Y-%m-%d").date(),
                datetime.min.time(), tzinfo=timezone.utc,
            )
        if cutoff.tzinfo is None:
            cutoff = cutoff.replace(tzinfo=timezone.utc)
        result = []
        for s in sessions:
            ts = s.get("last_event_at") or s.get("started_at") or ""
            try:
                ev_dt = datetime.fromisoformat(ts.replace("Z", "+00:00"))
                if ev_dt.tzinfo is None:
                    ev_dt = ev_dt.replace(tzinfo=timezone.utc)
                if ev_dt >= cutoff:
                    result.append(s)
            except ValueError:
                continue
        return result
    if args.today:
        today = datetime.now(timezone.utc).date()
        result = []
        for s in sessions:
            ts = s.get("last_event_at") or s.get("started_at") or ""
            try:
                ev_dt = datetime.fromisoformat(ts.replace("Z", "+00:00"))
                if ev_dt.date() == today:
                    result.append(s)
            except ValueError:
                continue
        return result
    if args.all:
        return sessions
    return []


def copy_session(s: dict, dest_repo: Path, dry_run: bool) -> tuple[bool, str]:
    src_root = staging_root() / s["github_login"]
    src_jsonl = src_root / s["file_path"].split(f"{s['github_login']}/", 1)[-1] \
        if "logs/" in s["file_path"] else None
    if src_jsonl is None or not src_jsonl.exists():
        date_part, fname = None, None
        if s["file_path"].count("/") >= 2:
            parts = s["file_path"].split("/")
            date_part, fname = parts[-2], parts[-1]
        if date_part and fname:
            src_jsonl = src_root / date_part / fname
    if not src_jsonl or not src_jsonl.exists():
        return False, f"source jsonl not found for session {s['session_id']}"

    rel_inside = src_jsonl.relative_to(src_root)
    dest_jsonl = dest_repo / "logs" / s["github_login"] / rel_inside

    if dry_run:
        return True, f"[dry-run] would copy {src_jsonl} -> {dest_jsonl}"

    dest_jsonl.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(src_jsonl, dest_jsonl)

    actual_count = sum(1 for line in dest_jsonl.read_text(encoding="utf-8").splitlines() if line.strip())
    s["event_count"] = actual_count
    s["file_path"] = f"logs/{s['github_login']}/{rel_inside}"

    update_dest_manifest(s, dest_repo)
    return True, f"copied -> {dest_jsonl.relative_to(dest_repo)} ({actual_count} events)"


def update_dest_manifest(s: dict, dest_repo: Path) -> None:
    member_dir = dest_repo / "logs" / s["github_login"]
    manifest_path = member_dir / "manifest.json"
    if manifest_path.exists():
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    else:
        src_manifest_path = staging_root() / s["github_login"] / "manifest.json"
        src_manifest = json.loads(src_manifest_path.read_text(encoding="utf-8"))
        manifest = {
            "schema_version": src_manifest.get("schema_version", "1.0"),
            "team_id": src_manifest.get("team_id", ""),
            "github_login": s["github_login"],
            "generator": src_manifest.get("generator", ""),
            "sessions": [],
        }
    existing = next((x for x in manifest["sessions"]
                     if x.get("session_id") == s["session_id"]), None)
    src_manifest_path = staging_root() / s["github_login"] / "manifest.json"
    src_manifest = json.loads(src_manifest_path.read_text(encoding="utf-8"))
    src_entry = next((x for x in src_manifest.get("sessions", [])
                      if x.get("session_id") == s["session_id"]), None)
    if src_entry is None:
        return
    entry = dict(src_entry)
    if "event_count" in s:
        entry["event_count"] = s["event_count"]
    if "file_path" in s:
        entry["file_path"] = s["file_path"]
    if existing:
        existing.update(entry)
    else:
        manifest["sessions"].append(entry)
    manifest["updated_at"] = datetime.now(timezone.utc).isoformat()
    manifest_path.write_text(json.dumps(manifest, indent=2, ensure_ascii=False),
                             encoding="utf-8")


def cmd_list(args, sessions: list[dict]) -> int:
    if not sessions:
        print("No sessions in staging.")
        print(f"Staging path: {staging_root()}")
        return 0
    print(f"{'session_id':<40} {'tool':<12} {'last_event_at':<26} "
          f"{'events':>6}  model")
    print("-" * 100)
    for s in sorted(sessions, key=lambda x: x.get("last_event_at") or ""):
        sid = (s["session_id"] or "")[:38]
        tool = s.get("tool", "")[:10]
        last = s.get("last_event_at", "")[:25]
        cnt = s.get("event_count", 0)
        model = s.get("model", "")
        print(f"{sid:<40} {tool:<12} {last:<26} {cnt:>6}  {model}")
    return 0


def cmd_backfill(args) -> int:
    dest = Path(args.dest) if args.dest else repo_root()
    if dest is None:
        sys.stderr.write("Cannot detect demo repo. "
                         "Run inside the repo or pass --dest.\n")
        return 2

    if args.force:
        staging = staging_root()
        if staging.exists():
            print(f"[--force] wiping staging at {staging}")
            shutil.rmtree(staging)

    claude_projects = Path.home() / ".claude" / "projects"
    if not claude_projects.is_dir():
        sys.stderr.write(f"No Claude Code history found at {claude_projects}\n")
        return 1

    skill_root = Path(__file__).resolve().parent.parent
    core_py = skill_root / "adapters" / "shared" / "snapshot_core.py"
    if not core_py.exists():
        sys.stderr.write(f"Cannot find snapshot_core.py at {core_py}\n")
        return 1

    transcripts = sorted(claude_projects.glob("*/*.jsonl"))
    if not transcripts:
        sys.stderr.write("No transcript files found in Claude Code history.\n")
        return 0

    env_vars = subprocess.check_output(
        ["bash", "-c",
         "source ~/.claude/contest-collector.env 2>/dev/null && "
         "echo \"TEAM_ID=${TEAM_ID:-}\" && echo \"GITHUB_LOGIN=${GITHUB_LOGIN:-}\""],
        text=True,
    ).strip()
    env_map = dict(line.split("=", 1) for line in env_vars.splitlines() if "=" in line)
    team_id = env_map.get("TEAM_ID", "").strip()
    github_login = env_map.get("GITHUB_LOGIN", "").strip()
    if not team_id:
        sys.stderr.write("TEAM_ID not found. Run install.sh first.\n")
        return 2
    if not github_login:
        sys.stderr.write("GITHUB_LOGIN not found in ~/.claude/contest-collector.env. "
                         "Re-run install.sh with --github-login <your-name>.\n")
        return 2

    print(f"Found {len(transcripts)} transcript(s) in Claude Code history.")
    print(f"Destination: {dest}/logs/")
    print(f"GitHub login: {github_login}")
    print()

    child_env = {**subprocess.os.environ, "TEAM_ID": team_id,
                 "GITHUB_LOGIN": github_login, "CWD": str(dest)}

    success = 0
    skipped = 0
    for t in transcripts:
        sid = t.stem
        payload = json.dumps({
            "session_id": sid,
            "cwd": str(dest),
            "transcript_path": str(t),
            "hook_event_name": "SessionEnd",
        })
        try:
            result = subprocess.run(
                [sys.executable, str(core_py), "--tool", "claude-code"],
                input=payload, text=True, capture_output=True,
                env=child_env,
                cwd=str(dest),
            )
            if result.returncode == 0:
                if "captured" in result.stderr:
                    success += 1
                    print(f"  ✅ {sid[:12]}  {result.stderr.strip().split('-> ')[-1] if '-> ' in result.stderr else 'ok'}")
                else:
                    skipped += 1
            else:
                print(f"  ⚠️  {sid[:12]}  {result.stderr.strip()[:80]}")
        except Exception as e:
            print(f"  ❌ {sid[:12]}  {e}")

    print(f"\nBackfill done: {success} imported, {skipped} skipped (already captured or empty).")
    if success > 0:
        print("Next: git add logs/ && git commit -s -m 'logs: backfill history' && git push")
    return 0


def main() -> int:
    p = argparse.ArgumentParser(
        description="Export AI Coding sessions from staging to demo repo logs/.",
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    p.add_argument("--list", action="store_true",
                   help="List all sessions in staging without exporting.")
    p.add_argument("--latest", action="store_true",
                   help="Export only the most recent session.")
    p.add_argument("--session", metavar="SID",
                   help="Export a specific session by id.")
    p.add_argument("--today", action="store_true",
                   help="Export sessions from today (UTC).")
    p.add_argument("--since", metavar="DATE",
                   help="Export sessions since a date (YYYY-MM-DD).")
    p.add_argument("--all", action="store_true",
                   help="Export every session in staging.")
    p.add_argument("--backfill", action="store_true",
                   help="Scan Claude Code history (~/.claude/projects/) and "
                        "re-process all transcripts. Recovers sessions that "
                        "were created before the hook was installed.")
    p.add_argument("--force", action="store_true",
                   help="With --backfill, wipe the local staging first so all "
                        "transcripts are re-processed even if they were "
                        "captured before. Useful after cleaning logs/ to "
                        "rebuild from scratch.")
    p.add_argument("--github-login", metavar="LOGIN",
                   help="Restrict to one member's sessions.")
    p.add_argument("--dest", metavar="PATH",
                   help="Destination repo path. Defaults to git rev-parse --show-toplevel.")
    p.add_argument("--dry-run", action="store_true",
                   help="Force preview mode, do not write.")
    p.add_argument("--confirm", action="store_true",
                   help="Required to actually export. Without it, the tool only previews.")
    args = p.parse_args()

    sessions = list_sessions(args.github_login)

    if args.list:
        return cmd_list(args, sessions)

    if args.backfill:
        return cmd_backfill(args)

    if not any([args.latest, args.session, args.today, args.since, args.all]):
        p.print_help()
        sys.stderr.write("\nNothing to do. Pick one of "
                         "--latest, --session, --today, --since, --all, --list, --backfill.\n")
        return 2

    selected = filter_sessions(sessions, args)
    if not selected:
        sys.stderr.write("No sessions matched.\n")
        return 1

    dest = Path(args.dest) if args.dest else repo_root()
    if dest is None:
        sys.stderr.write("Cannot detect demo repo. "
                         "Run inside the repo or pass --dest.\n")
        return 2

    preview_only = args.dry_run or not args.confirm
    rc = 0
    for s in selected:
        ok, msg = copy_session(s, dest, preview_only)
        prefix = "✅" if ok else "❌"
        print(f"{prefix} {s['session_id'][:12]}  {msg}")
        if not ok:
            rc = 1

    if preview_only:
        print(f"\n[preview] {len(selected)} session(s) shown above. "
              "Nothing was written.")
        print("Re-run with --confirm to actually export, e.g.:")
        if args.latest:
            print("  python3 tools/export-session.py --latest --confirm")
        elif args.session:
            print(f"  python3 tools/export-session.py --session {args.session} --confirm")
        elif args.today:
            print("  python3 tools/export-session.py --today --confirm")
        elif args.since:
            print(f"  python3 tools/export-session.py --since {args.since} --confirm")
        elif args.all:
            print("  python3 tools/export-session.py --all --confirm")
    else:
        print(f"\n{len(selected)} session(s) exported to {dest}/logs/")
        print("Next: git add logs/ && git commit && git push")

    return rc


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
# openvela AI Contest - Claude Code & Codex shared snapshot core
#
# Claude Code and OpenAI Codex CLI share ~90% of their hook stdin JSON schema
# (Codex source comments reference Claude Code's schema directly).
# Both tools share the same Python core; only a thin wrapper differentiates the tool name.
#
# Invocation (Claude Code Stop / SessionEnd hook or Codex Stop hook):
#   echo "$STDIN_JSON" | python3 snapshot_core.py --tool claude-code
#   echo "$STDIN_JSON" | python3 snapshot_core.py --tool codex
#
# Required env: TEAM_ID
# Optional env: SESSION_LOG_DIR
#
# Exit codes:
#   0  Success (including throttled skips)
#   1  Failed but recorded in errors/
#   2  TEAM_ID missing or fatal config error

from __future__ import annotations

import argparse
import json
import os
import re
import shutil
import subprocess
import sys
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

sys.path.insert(0, str(Path(__file__).resolve().parent))
from get_github_login import resolve_github_login

VERSION = "1.2.0"
SCHEMA_VERSION = "1.0"

DEFAULT_REDACT_RULES = [
    (re.compile(r"sk-[A-Za-z0-9_-]{20,}"), "sk-***REDACTED***"),
    (re.compile(r"ghp_[A-Za-z0-9]{36}"), "ghp_***REDACTED***"),
    (re.compile(r"Bearer\s+[A-Za-z0-9._\-+/=]+"), "Bearer ***REDACTED***"),
]

SKIP_BLOCK_TYPES = {"image"}


def iso_now() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.") + f"{datetime.now(timezone.utc).microsecond // 1000:03d}Z"


def local_date() -> str:
    d = datetime.now()
    return f"{d.year:04d}-{d.month:02d}-{d.day:02d}"


def fs_timestamp() -> str:
    d = datetime.now()
    return d.strftime("%Y%m%d_%H%M%S")


def report_error(log_root: Path, kind: str, ctx: dict, exc: BaseException | str) -> None:
    try:
        errors_dir = log_root / "errors"
        errors_dir.mkdir(parents=True, exist_ok=True)
        err_path = errors_dir / f"{fs_timestamp()}_{kind}.err"
        payload = {
            "ts": iso_now(),
            "kind": kind,
            "tool": ctx.get("tool", "unknown"),
            "team_id": os.environ.get("TEAM_ID", ""),
            "version": VERSION,
            "context": ctx,
            "message": str(exc),
        }
        err_path.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    except Exception:
        pass
    sys.stderr.write(
        f"[session-log] ERROR kind={kind} tool={ctx.get('tool','?')} "
        f"team={os.environ.get('TEAM_ID','')}: {exc}\n"
    )


def load_redact_rules(log_root: Path) -> list[tuple[re.Pattern[str], str]]:
    custom_path = log_root / "redact.json"
    if not custom_path.exists():
        return DEFAULT_REDACT_RULES
    try:
        custom = json.loads(custom_path.read_text(encoding="utf-8"))
        compiled = []
        for r in custom:
            flags = 0
            if "i" in r.get("flags", ""):
                flags |= re.IGNORECASE
            compiled.append((re.compile(r["pattern"], flags), r.get("replacement", "***REDACTED***")))
        return [*DEFAULT_REDACT_RULES, *compiled]
    except Exception:
        return DEFAULT_REDACT_RULES


def redact_value(value: Any, rules: list[tuple[re.Pattern[str], str]], counter: list[int]) -> Any:
    if isinstance(value, str):
        out = value
        for pattern, replacement in rules:
            new_out, n = pattern.subn(replacement, out)
            counter[0] += n
            out = new_out
        return out
    if isinstance(value, list):
        return [redact_value(v, rules, counter) for v in value]
    if isinstance(value, dict):
        return {k: redact_value(v, rules, counter) for k, v in value.items()}
    return value


def load_transcript(transcript_path: Path) -> list[dict] | None:
    if not transcript_path.exists():
        return None
    try:
        events = []
        for line in transcript_path.read_text(encoding="utf-8").splitlines():
            line = line.strip()
            if not line:
                continue
            try:
                events.append(json.loads(line))
            except json.JSONDecodeError:
                continue
        return events
    except Exception:
        return None


def expand_claude_event(raw_event: dict, fallback_ts: str) -> list[dict]:
    """Convert one Claude Code transcript event to zero-or-more contest events.

    Schema (verified against real ~/.claude/projects/*.jsonl):
      - top-level type: user / assistant / system / progress / file-history-snapshot / ...
      - real conversation lives in .message
      - assistant.message.content is a list of blocks: text / thinking / tool_use
      - user.message.content is str (plain input) OR list (containing tool_result blocks)
      - tool_result blocks carry tool_use_id pairing back to assistant tool_use
    """
    out: list[dict] = []
    top_type = raw_event.get("type")
    ts = raw_event.get("timestamp") or fallback_ts

    if top_type in ("progress", "file-history-snapshot", "queue-operation", "permission-mode", "agent-name", "summary", "attachment"):
        return out

    msg = raw_event.get("message") or {}
    role = (msg.get("role") or top_type or "system").lower()
    content = msg.get("content")
    model = msg.get("model")
    usage = msg.get("usage") or {}
    tokens_in = usage.get("input_tokens")
    tokens_out = usage.get("output_tokens")

    common = {"ts": ts}
    if model:
        common["model"] = model
    if isinstance(tokens_in, int):
        common["tokens_in"] = tokens_in
    if isinstance(tokens_out, int):
        common["tokens_out"] = tokens_out

    if isinstance(content, str):
        if content:
            out.append({**common, "role": role, "text": content})
        return out

    if not isinstance(content, list):
        return out

    for block in content:
        if not isinstance(block, dict):
            continue
        bt = block.get("type")
        if bt in SKIP_BLOCK_TYPES:
            continue
        if bt == "text":
            text = block.get("text", "")
            if text:
                out.append({**common, "role": role, "text": text})
        elif bt == "thinking":
            thinking = block.get("thinking") or block.get("text") or ""
            if thinking:
                out.append({**common, "role": role, "thinking": thinking})
        elif bt == "tool_use":
            out.append({
                **common,
                "role": "tool",
                "tool_name": block.get("name", "unknown"),
                "tool_call_id": block.get("id", f"call_{len(out)}"),
                "input": block.get("input"),
                "output": None,
            })
        elif bt == "tool_result":
            tool_call_id = block.get("tool_use_id", f"call_{len(out)}")
            result_content = block.get("content")
            out.append({
                **common,
                "role": "tool",
                "tool_name": "<result>",
                "tool_call_id": tool_call_id,
                "input": None,
                "output": result_content,
                "is_error": bool(block.get("is_error")),
            })
        else:
            out.append({
                **common,
                "role": role,
                "text": f"[unsupported block type: {bt}]",
                "metadata": {"dropped": True, "original_type": bt},
            })
    return out


def append_events(jsonl_path: Path, events: list[dict], session_id: str, team_id: str, github_login: str, tool: str, start_seq: int, redact_rules) -> dict:
    seq = start_seq
    redacted_total = 0
    lines = []
    for ev in events:
        counter = [0]
        redacted = redact_value(ev, redact_rules, counter)
        redacted_total += counter[0]
        out = {
            "schema_version": SCHEMA_VERSION,
            "session_id": session_id,
            "team_id": team_id,
            "github_login": github_login,
            "tool": tool,
            "seq": seq,
            **redacted,
        }
        if counter[0] > 0:
            out["redacted_count"] = counter[0]
        lines.append(json.dumps(out, ensure_ascii=False))
        seq += 1
    if not lines:
        return {"written": 0, "last_seq": start_seq - 1, "redacted": 0}
    jsonl_path.parent.mkdir(parents=True, exist_ok=True)
    with jsonl_path.open("a", encoding="utf-8") as f:
        f.write("\n".join(lines) + "\n")
    return {"written": len(lines), "last_seq": seq - 1, "redacted": redacted_total}


def read_manifest(member_dir: Path, team_id: str, github_login: str, tool: str) -> dict:
    path = member_dir / "manifest.json"
    if not path.exists():
        return {
            "schema_version": SCHEMA_VERSION,
            "team_id": team_id,
            "github_login": github_login,
            "generator": f"{tool}-collector@{VERSION}",
            "updated_at": iso_now(),
            "sessions": [],
        }
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        if data.get("team_id") != team_id:
            report_error(member_dir, "manifest_team_mismatch", {"tool": tool, "path": str(path)},
                         f"manifest.team_id={data.get('team_id')} but TEAM_ID env={team_id}")
        if data.get("github_login") and data.get("github_login") != github_login:
            report_error(member_dir, "manifest_login_mismatch", {"tool": tool, "path": str(path)},
                         f"manifest.github_login={data.get('github_login')} but detected={github_login}")
        return data
    except Exception as e:
        report_error(member_dir, "manifest_read", {"tool": tool, "path": str(path)}, e)
        return {
            "schema_version": SCHEMA_VERSION,
            "team_id": team_id,
            "github_login": github_login,
            "generator": f"{tool}-collector@{VERSION}",
            "updated_at": iso_now(),
            "sessions": [],
        }


def write_manifest(member_dir: Path, manifest: dict, team_id: str, github_login: str, tool: str) -> None:
    manifest["updated_at"] = iso_now()
    manifest["team_id"] = team_id
    manifest["github_login"] = github_login
    manifest["schema_version"] = SCHEMA_VERSION
    manifest["generator"] = f"{tool}-collector@{VERSION}"
    path = member_dir / "manifest.json"
    try:
        path.write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    except Exception as e:
        report_error(member_dir, "manifest_write", {"tool": tool, "path": str(path)}, e)


def get_repo_root() -> Path | None:
    try:
        out = subprocess.check_output(["git", "rev-parse", "--show-toplevel"], stderr=subprocess.PIPE, text=True)
        return Path(out.strip())
    except Exception:
        return None


# Privacy gate: only collect inside an openvela workspace, identified by a
# `.repo/` dir at the workspace root. Sessions outside it (personal projects)
# must never be collected. Returns the workspace root, or None if not inside.
def find_openvela_workspace_root(start_dir: Path) -> Path | None:
    try:
        cur = Path(start_dir).resolve()
        for candidate in [cur, *cur.parents]:
            if (candidate / ".repo").is_dir():
                return candidate
    except Exception:
        return None
    return None


def get_fallback_author() -> tuple[str, str]:
    fallback = os.environ.get("LOG_FALLBACK_EMAIL", "")
    if fallback:
        return fallback.split("@")[0], fallback
    ssh_dir = Path.home() / ".ssh"
    try:
        for f in ssh_dir.glob("*.pub"):
            content = f.read_text(encoding="utf-8").strip()
            parts = content.split()
            comment = parts[-1] if parts else ""
            if "@" in comment and not comment.startswith("ssh-"):
                return comment.split("@")[0], comment
    except Exception:
        pass
    return "contest-collector", "contest-collector@auto-commit.local"


def process_claude_stdin(stdin_data: dict, tool: str, team_id: str) -> int:
    """Claude Code Stop / SessionEnd hook stdin payload format:
        {
          "session_id": "...",
          "cwd": "...",
          "transcript_path": "/abs/path/.jsonl",
          "hook_event_name": "Stop" | "SessionEnd",
          ...
        }
    Codex Stop hook stdin payload schema is shared with Claude Code (sso_id/cwd/transcript_path use the same names).
    """
    session_id = stdin_data.get("session_id") or stdin_data.get("sessionId")
    cwd = stdin_data.get("cwd") or os.getcwd()
    transcript_path_str = stdin_data.get("transcript_path") or stdin_data.get("transcriptPath")

    if not session_id:
        sys.stderr.write("[session-log] missing session_id in stdin payload\n")
        return 1

    repo_root = get_repo_root() or Path(cwd)

    workspace_root = find_openvela_workspace_root(repo_root)
    if workspace_root is None:
        sys.stderr.write(
            "[session-log] not inside an openvela workspace (no .repo/ found); "
            "collection disabled for this session.\n"
        )
        return 0

    login_result = resolve_github_login(repo_root)
    if not login_result[0]:
        sys.stderr.write(
            "[session-log] FATAL: cannot detect GITHUB_LOGIN. "
            "Set GITHUB_LOGIN env, or run 'gh auth login', or fix git remote URL.\n"
        )
        return 2
    github_login = login_result[0]

    log_root = Path(os.environ.get("SESSION_LOG_DIR")
                    or (Path.home() / ".claude" / "contest-collector-staging"))
    member_dir = log_root / github_login
    try:
        member_dir.mkdir(parents=True, exist_ok=True)
    except Exception as e:
        sys.stderr.write(f"[session-log] cannot create member dir {member_dir}: {e}\n")
        return 1

    if not transcript_path_str:
        sys.stderr.write(
            "[session-log] skipping: stdin has no transcript_path "
            f"(event={stdin_data.get('hook_event_name', '?')}, "
            f"session={session_id[:12] if session_id else '?'})\n"
        )
        return 0
    transcript_path = Path(transcript_path_str)

    raw_events = load_transcript(transcript_path)
    if raw_events is None:
        report_error(member_dir, "transcript_unreadable", {"tool": tool, "transcript_path": str(transcript_path)},
                     f"cannot read or parse transcript at {transcript_path}")
        return 1

    manifest = read_manifest(member_dir, team_id, github_login, tool)
    entry = next((s for s in manifest.get("sessions", []) if s.get("session_id") == session_id), None)
    is_new = entry is None
    raw_watermark = entry.get("raw_event_count", 0) if entry else 0
    start_seq = entry.get("event_count", 0) if entry else 0

    new_raw = raw_events[raw_watermark:]
    if not new_raw:
        return 0

    contest_events = []
    for raw in new_raw:
        contest_events.extend(expand_claude_event(raw, fallback_ts=iso_now()))

    if not contest_events:
        if entry is not None:
            entry["raw_event_count"] = len(raw_events)
            write_manifest(member_dir, manifest, team_id, github_login, tool)
        return 0

    redact_rules = load_redact_rules(member_dir)
    if entry and entry.get("file_path"):
        existing_rel = entry["file_path"].split(f"{github_login}/", 1)[-1] \
            if f"{github_login}/" in entry["file_path"] else None
        if existing_rel:
            jsonl_path = member_dir / existing_rel
        else:
            jsonl_path = member_dir / local_date() / f"{tool}__{session_id}.jsonl"
    else:
        jsonl_path = member_dir / local_date() / f"{tool}__{session_id}.jsonl"

    try:
        result = append_events(jsonl_path, contest_events, session_id, team_id, github_login, tool, start_seq, redact_rules)
    except Exception as e:
        report_error(member_dir, "jsonl_append", {"tool": tool, "jsonl_path": str(jsonl_path)}, e)
        return 1

    new_event_count = (entry.get("event_count", 0) if entry else 0) + result["written"]
    rel_path = f"logs/{github_login}/{local_date()}/{tool}__{session_id}.jsonl"

    if is_new:
        first_ts = (raw_events[0].get("timestamp") if raw_events else None) or iso_now()
        entry = {
            "session_id": session_id,
            "tool": tool,
            "started_at": first_ts,
            "last_event_at": iso_now(),
            "event_count": new_event_count,
            "raw_event_count": len(raw_events),
            "file_path": rel_path,
            "collection_mode": "cli",
            "health": "ok",
        }
        last_assistant = next((e for e in reversed(raw_events) if (e.get("message") or {}).get("model")), None)
        if last_assistant:
            model = last_assistant.get("message", {}).get("model")
            if model:
                entry["model"] = model
        manifest.setdefault("sessions", []).append(entry)
    else:
        entry["last_event_at"] = iso_now()
        entry["event_count"] = new_event_count
        entry["raw_event_count"] = len(raw_events)
        entry["file_path"] = rel_path
        if result["redacted"] > 0:
            entry["redacted_count_total"] = entry.get("redacted_count_total", 0) + result["redacted"]

    write_manifest(member_dir, manifest, team_id, github_login, tool)

    auto_export_to_repo(
        repo_root, member_dir, jsonl_path, session_id,
        team_id, github_login, tool,
    )

    sys.stderr.write(
        f"[session-log] captured {result['written']} event(s) -> {rel_path}\n"
    )

    return 0


def auto_export_to_repo(repo_root: Path, staging_member_dir: Path, staging_jsonl: Path,
                        session_id: str, team_id: str, github_login: str, tool: str) -> None:
    try:
        dest_member = repo_root / "logs" / github_login
        dest_jsonl = dest_member / staging_jsonl.relative_to(staging_member_dir)
        dest_jsonl.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(staging_jsonl, dest_jsonl)

        actual_count = sum(1 for line in dest_jsonl.read_text(encoding="utf-8").splitlines() if line.strip())

        staging_manifest = read_manifest(staging_member_dir, team_id, github_login, tool)
        src_entry = next((s for s in staging_manifest.get("sessions", [])
                          if s.get("session_id") == session_id), None)
        if src_entry is None:
            return
        src_entry["event_count"] = actual_count
        src_entry["file_path"] = f"logs/{github_login}/{staging_jsonl.relative_to(staging_member_dir)}"

        dest_manifest = read_manifest(dest_member, team_id, github_login, tool)
        existing = next((s for s in dest_manifest.get("sessions", [])
                         if s.get("session_id") == session_id), None)
        if existing:
            existing.update(src_entry)
        else:
            dest_manifest.setdefault("sessions", []).append(src_entry)
        write_manifest(dest_member, dest_manifest, team_id, github_login, tool)
    except Exception as e:
        report_error(staging_member_dir, "auto_export", {"repo_root": str(repo_root), "session_id": session_id}, e)


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--tool", required=True, choices=["claude-code", "codex"])
    args = parser.parse_args()

    team_id = os.environ.get("TEAM_ID", "").strip()
    if not team_id:
        sys.stderr.write(
            "[session-log] FATAL: TEAM_ID env var not set, refusing to write log to avoid mis-attribution\n"
        )
        return 2

    sys.stderr.write(f"[session-log] tool={args.tool} team={team_id} version={VERSION}\n")

    try:
        stdin_text = sys.stdin.read()
        if not stdin_text.strip():
            sys.stderr.write("[session-log] stdin empty, nothing to do\n")
            return 0
        stdin_data = json.loads(stdin_text)
    except json.JSONDecodeError as e:
        sys.stderr.write(f"[session-log] cannot parse stdin JSON: {e}\n")
        return 1

    return process_claude_stdin(stdin_data, args.tool, team_id)


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
# Render contest session JSONL into human-readable formats.
#
# Usage:
#   render-log.py <jsonl-path>                    # Terminal output (default, color)
#   render-log.py <jsonl-path> --format html > out.html
#   render-log.py <jsonl-path> --format md
#   render-log.py <member-dir>                    # Render all sessions under a member dir
#
# Output formats: terminal (default) / html / md

from __future__ import annotations

import argparse
import html
import json
import sys
from datetime import datetime, timezone
from pathlib import Path


ROLE_BADGE = {
    "user": ("👤", "USER", "\033[1;36m"),
    "assistant": ("🤖", "ASSISTANT", "\033[1;32m"),
    "tool": ("🔧", "TOOL", "\033[1;33m"),
    "system": ("⚙️ ", "SYSTEM", "\033[1;90m"),
}
RESET = "\033[0m"
DIM = "\033[2m"
BOLD = "\033[1m"


def fmt_time(ts: str) -> str:
    try:
        dt = datetime.fromisoformat(ts.replace("Z", "+00:00"))
        local = dt.astimezone()
        return local.strftime("%H:%M:%S")
    except Exception:
        return ts


def truncate(s: str, n: int = 200) -> str:
    if len(s) <= n:
        return s
    return s[:n] + f" ... [+{len(s) - n} chars]"


def fmt_tool_io(value, max_str: int = 500, indent: int = 4) -> str:
    if value is None:
        return "(empty)"
    if isinstance(value, str):
        return truncate(value, max_str)
    try:
        formatted = json.dumps(value, ensure_ascii=False, indent=2)
        return "\n".join(" " * indent + line for line in formatted.split("\n"))
    except Exception:
        return repr(value)


def render_terminal(events: list[dict], use_color: bool = True) -> list[str]:
    lines = []
    if not events:
        lines.append("(empty)")
        return lines

    head = events[0]
    sep = "═" * 76
    lines.append(sep)
    lines.append(f"  Session: {head.get('session_id', '?')}")
    lines.append(f"  Tool:    {head.get('tool', '?')}")
    lines.append(f"  Team:    {head.get('team_id', '?')}")
    lines.append(f"  Member:  {head.get('github_login', '?')}")
    lines.append(f"  Events:  {len(events)}")
    lines.append(sep)
    lines.append("")

    total_tokens_in = 0
    total_tokens_out = 0

    for ev in events:
        role = ev.get("role", "?")
        emoji, label, color = ROLE_BADGE.get(role, ("·", role.upper(), ""))
        time = fmt_time(ev.get("ts", ""))
        seq = ev.get("seq", "?")

        if use_color:
            header = f"{color}{emoji} [{label}]{RESET} {DIM}seq={seq}  {time}{RESET}"
        else:
            header = f"{emoji} [{label}] seq={seq}  {time}"

        meta_bits = []
        if ev.get("model"):
            meta_bits.append(f"model={ev['model']}")
        if ev.get("tokens_in") is not None:
            total_tokens_in += ev["tokens_in"]
            meta_bits.append(f"in={ev['tokens_in']}")
        if ev.get("tokens_out") is not None:
            total_tokens_out += ev["tokens_out"]
            meta_bits.append(f"out={ev['tokens_out']}")
        if ev.get("redacted_count"):
            meta_bits.append(f"REDACTED×{ev['redacted_count']}")
        if meta_bits:
            if use_color:
                header += f"  {DIM}({', '.join(meta_bits)}){RESET}"
            else:
                header += f"  ({', '.join(meta_bits)})"

        lines.append(header)
        lines.append("─" * 76)

        if role == "tool":
            tool_name = ev.get("tool_name", "?")
            tool_call_id = ev.get("tool_call_id", "")
            is_result = tool_name == "<result>"
            err_marker = "  ❌ ERROR" if ev.get("is_error") else ""

            if is_result:
                lines.append(f"  ⤷  Tool result for: {tool_call_id[:20]}{err_marker}")
                lines.append(f"  Output:")
                lines.append(fmt_tool_io(ev.get("output"), max_str=800))
            else:
                lines.append(f"  → Tool call: {tool_name}  [{tool_call_id[:20]}]")
                lines.append(f"  Input:")
                lines.append(fmt_tool_io(ev.get("input"), max_str=400))
                if ev.get("output") is not None:
                    lines.append(f"  Output:")
                    lines.append(fmt_tool_io(ev.get("output"), max_str=400))
        else:
            if ev.get("thinking"):
                if use_color:
                    lines.append(f"  {DIM}💭 thinking:{RESET}")
                else:
                    lines.append(f"  💭 thinking:")
                for line in ev["thinking"].split("\n"):
                    if use_color:
                        lines.append(f"    {DIM}{line}{RESET}")
                    else:
                        lines.append(f"    {line}")
            if ev.get("text"):
                for line in ev["text"].split("\n"):
                    lines.append(f"  {line}")

        if ev.get("files_touched"):
            files_str = ", ".join(ev["files_touched"])
            if use_color:
                lines.append(f"  {DIM}📂 files: {files_str}{RESET}")
            else:
                lines.append(f"  📂 files: {files_str}")

        lines.append("")

    if total_tokens_in or total_tokens_out:
        lines.append(sep)
        lines.append(f"  Total tokens: in={total_tokens_in}  out={total_tokens_out}  total={total_tokens_in + total_tokens_out}")
        lines.append(sep)

    return lines


def render_markdown(events: list[dict]) -> list[str]:
    lines = []
    if not events:
        return ["_(empty session)_"]

    head = events[0]
    lines.append(f"# Session `{head.get('session_id', '?')}`")
    lines.append("")
    lines.append(f"- **Tool**: `{head.get('tool', '?')}`")
    lines.append(f"- **Team**: `{head.get('team_id', '?')}`")
    lines.append(f"- **Member**: `{head.get('github_login', '?')}`")
    lines.append(f"- **Events**: {len(events)}")
    lines.append("")
    lines.append("---")
    lines.append("")

    role_label = {"user": "👤 User", "assistant": "🤖 Assistant",
                  "tool": "🔧 Tool", "system": "⚙️ System"}

    for ev in events:
        role = ev.get("role", "?")
        label = role_label.get(role, role.upper())
        time = fmt_time(ev.get("ts", ""))
        seq = ev.get("seq", "?")

        meta = []
        if ev.get("model"):
            meta.append(f"model: `{ev['model']}`")
        if ev.get("tokens_in") is not None:
            meta.append(f"tokens: {ev.get('tokens_in')}/{ev.get('tokens_out', '?')}")
        if ev.get("redacted_count"):
            meta.append(f"⚠️ redacted×{ev['redacted_count']}")
        meta_str = " · ".join(meta)
        suffix = f"  _{meta_str}_" if meta_str else ""

        lines.append(f"## {label} · seq={seq} · {time}{suffix}")
        lines.append("")

        if role == "tool":
            name = ev.get("tool_name", "?")
            call_id = ev.get("tool_call_id", "")
            if name == "<result>":
                lines.append(f"**↩ Result for** `{call_id}`")
                if ev.get("is_error"):
                    lines.append("")
                    lines.append("> ❌ Tool returned an error.")
                lines.append("")
                lines.append("```")
                output = ev.get("output", "")
                lines.append(str(output) if not isinstance(output, str) else output)
                lines.append("```")
            else:
                lines.append(f"**🔧 Tool call**: `{name}`  ·  id: `{call_id}`")
                lines.append("")
                lines.append("**Input**:")
                lines.append("```json")
                lines.append(json.dumps(ev.get("input"), ensure_ascii=False, indent=2))
                lines.append("```")
                if ev.get("output"):
                    lines.append("**Output**:")
                    lines.append("```")
                    lines.append(str(ev["output"]))
                    lines.append("```")
        else:
            if ev.get("thinking"):
                lines.append("> 💭 **Thinking**:")
                for line in ev["thinking"].split("\n"):
                    lines.append(f"> {line}")
                lines.append("")
            if ev.get("text"):
                lines.append(ev["text"])

        if ev.get("files_touched"):
            lines.append("")
            lines.append(f"📂 _files touched_: {', '.join(f'`{f}`' for f in ev['files_touched'])}")

        lines.append("")
        lines.append("---")
        lines.append("")

    return lines


