"""Scan transcripts for project milestones and confirm the WSL session belongs to openvela."""
import json
import re
from pathlib import Path

HOME = Path.home()
DIRS = [HOME / ".claude" / "projects" / "E--openvela",
        HOME / ".claude" / "projects" / "--wsl-localhost-Ubuntu-22-04-home-dev"]

PATTERNS = {
    "repo_sync": re.compile(r"repo sync", re.I),
    "tflite": re.compile(r"tflite|tensorflow|\bTFLM\b|micro_interpreter|person_detect", re.I),
    "espeak_tts": re.compile(r"espeak|pico2wave|tts", re.I),
    "build_ok": re.compile(r"build (succeeded|complete)|Build complete|编译成功|构建成功", re.I),
    "qemu": re.compile(r"qemu", re.I),
    "ai_glasses": re.compile(r"ai_glasses", re.I),
}


def load(p: Path):
    out = []
    for line in p.read_text(encoding="utf-8", errors="replace").splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            out.append(json.loads(line))
        except json.JSONDecodeError:
            pass
    return out


def all_text(e):
    msg = e.get("message") or {}
    c = msg.get("content")
    parts = []
    if isinstance(c, str):
        parts.append(c)
    elif isinstance(c, list):
        for b in c:
            if not isinstance(b, dict):
                continue
            for k in ("text", "thinking"):
                if b.get(k):
                    parts.append(str(b[k]))
            if b.get("input") is not None:
                parts.append(json.dumps(b["input"], ensure_ascii=False)[:4000])
            if b.get("content") is not None and b.get("type") == "tool_result":
                parts.append(json.dumps(b["content"], ensure_ascii=False)[:4000])
    return "\n".join(parts)


for d in DIRS:
    if not d.is_dir():
        continue
    for f in sorted(d.glob("*.jsonl")):
        ev = load(f)
        counts = {k: 0 for k in PATTERNS}
        first_hit = {}
        for e in ev:
            t = all_text(e)
            for k, rx in PATTERNS.items():
                if rx.search(t):
                    counts[k] += 1
                    first_hit.setdefault(k, e.get("timestamp", "?"))
        print("=" * 90)
        print(f"{d.name}/{f.name}")
        for k in PATTERNS:
            if counts[k]:
                print(f"   {k:<12} hits={counts[k]:<5} first={first_hit[k]}")

